 1	# Login service
 2	A small Node service. src/login.js checks a username and a password.
 3	Read docs/constraints.md before designing anything for it.
 4	# Constraints
 5	- The service runs as ONE process on ONE host.
 6	- No Redis, database server or other external store may be added.
 7	- State may live in process memory only; losing it on restart is fine.
 8	import { users } from "./users.js";
 9	
10	export function login(username, password, ip) {
11	  const user = users.get(username);
12	  if (!user) return { ok: false, error: "unknown user" };
13	  if (user.password !== password) return { ok: false, error: "wrong password" };
14	  return { ok: true, userId: user.id };
15	}
16	export const users = new Map([["ada", { id: 1, password: "correct horse" }]]);

